import sys
import math

SIZE = 1000002

s = [0] * SIZE
p = [0] * SIZE
np = 0
min_val = 0

def sieve():
    global np
    for i in range(2, SIZE):
        if s[i] == 0:
            p[np] = i
            np += 1
            j = 2
            while i * j < SIZE:
                s[i * j] = 1
                j += 1

def solve(x, l):
    global min_val
    ox = x
    lf = -1

    if x < min_val:
        min_val = x

    if l == 0:
        return

    i = 0
    while i < np and p[i] * p[i] <= x:
        if ox % p[i] == 0:
            lf = max(lf, p[i])
            while ox % p[i] == 0:
                ox //= p[i]
        i += 1

    if ox > 1 and ox != x:
        lf = max(lf, ox)

    if lf == -1:
        return

    if l == 1:
        x = x - lf + 1
        if x < min_val:
            min_val = x
        return

    d = x - lf + 1
    limit = lf * (x // lf)
    while d < limit:
        solve(d, l - 1)
        d += 1

def main():
    global min_val
    s[0] = 1
    s[1] = 1
    sieve()
    min_val = 2**31 - 1

    data = sys.stdin.read().strip()
    if not data:
        return
    x2 = int(data)
    solve(x2, 2)
    print(min_val)

if __name__ == "__main__":
    main()

